#!/bin/bash
# Fetch Adobe's InDesign 2026 IDML RelaxNG schemas (generated by InDesign's app.generateIDMLSchema(), with the
# datatype.rnc prose-leak fix applied) from github.com/metanorma/idml, pinned to the commit this skill was tested on.
# They are not redistributed here. Or generate your own: InDesign > Scripts > GeneratePackageSchema.jsx (Adobe IDML Cookbook).
set -euo pipefail
SHA=adc6a109df73a60496a0b8e1fc863b8d3b538b38
S="$(cd "$(dirname "$0")/.." && pwd)/schemas"
BASE="https://raw.githubusercontent.com/metanorma/idml/$SHA/reference-docs/schemas/package"
for f in designmap.rnc datatype.rnc Resources/Graphic.rnc Resources/Styles.rnc Resources/Fonts.rnc Resources/Preferences.rnc \
         XML/BackingStory.rnc XML/Tags.rnc XML/Mapping.rnc Stories/Story.rnc Spreads/Spread.rnc MasterSpreads/MasterSpread.rnc; do
  mkdir -p "$S/$(dirname "$f")"
  curl -sfL "$BASE/$f" -o "$S/$f" || { echo "fetch failed: $f"; exit 1; }
done
echo "schemas -> $S (metanorma/idml @ ${SHA:0:7})"
